// Render-time French typography: French high punctuation takes a no-break
// space (docs/I18N.md §4, docs/hebrew-alphabet-editorial-rules.fr.md).
//
// Hand-authored FR copy carries the right character in the source string. This
// filter exists for the French text this repo does NOT author by hand and must
// not edit at rest:
//
//   - FR lesson snapshots (src/content/lessons/fr/**) are generated by
//     scripts/normalize-lesson.mjs and verified against a pinned raw SHA.
//   - FR phrase copy (src/data/hebrew-phrases.ts) is pinned by the editorial
//     sign-off SHA in `phraseReviewFr`; editing it would invalidate the owner's
//     approval.
//
// So the correction happens on the way to the page instead, leaving both
// sources byte-identical.

const NBSP = ' ';

/** Idempotent: a space that is already a no-break space is left alone. */
export function frTypography(text) {
  if (typeof text !== 'string' || !text) return text;
  return text
    // A regular space before : ; ? ! » becomes a no-break space. Requires a
    // non-space before it, so " :" at the very start of a run is left alone.
    // Lookaround rather than captures, so the space is the only thing consumed
    // and adjacent runs both match — "« de rien » ; en" needs the fix twice,
    // on "n »" and on "» ;".
    .replace(/(?<=\S) (?=[:;?!»])/g, NBSP)
    // « takes a no-break space after it.
    .replace(/(?<=«) /g, NBSP);
}

/** Maps frTypography over every string in a value, preserving shape. Safe on
 *  ids, hrefs, Hebrew and transliterations: none of them has a space before
 *  French high punctuation, so the filter is a no-op there. */
export function frTypographyDeep(value) {
  if (typeof value === 'string') return frTypography(value);
  if (Array.isArray(value)) return value.map(frTypographyDeep);
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value)) out[key] = frTypographyDeep(value[key]);
    return out;
  }
  return value;
}

/** Locale gate: en passes through untouched, so EN output never changes. */
export function localizeTypography(locale, value) {
  return locale === 'fr' ? frTypographyDeep(value) : value;
}
